# python.tui.main (python/tui.py:56) — requirement 2-1
"""Tests for tui.main (unit 28faeb62248a, Requirement 2-1).

Every external boundary main() touches -- the terminal (termios/tty), stdin,
select, the clock and the audio NoteEngine -- is replaced with an in-process
stub, so no real device, terminal state or audio stream is ever opened.
"""

import io
import re
import sys as _real_sys
from types import SimpleNamespace
from unittest import mock

import pytest

# sounddevice is a real audio-device binding pulled in by audio_logic, which
# tui imports at module scope. Stub it BEFORE importing tui.
_real_sys.modules.setdefault("sounddevice", mock.MagicMock())

import tui  # noqa: E402
from key_mapping import color_for_key, key_order  # noqa: E402


class _FakeStdin:
    def __init__(self, chars):
        self._chars = list(chars)

    def fileno(self):
        return 0

    def read(self, n=1):
        return self._chars.pop(0) if self._chars else "q"


class _FakeEngine:
    def __init__(self, on_state_change=None):
        self.on_state_change = on_state_change
        self.downs = []
        self.ups = []
        self.closed = False

    def key_down(self, key):
        self.downs.append(key)
        if self.on_state_change is not None:
            self.on_state_change(key, True)

    def key_up(self, key):
        self.ups.append(key)
        if self.on_state_change is not None:
            self.on_state_change(key, False)

    def close(self):
        self.closed = True


def _run_main(script, times=None):
    """Drive tui.main().

    `script` is one entry per loop iteration: a character string means stdin is
    ready and yields that character, None means select() reported no input.
    `times` supplies the value time.monotonic() returns on each iteration.
    Returns (result, engine, drawn_output, termios_stub, tty_stub).
    """
    readiness = list(script)
    stdin = _FakeStdin([c for c in script if c is not None])
    stdout = io.StringIO()
    fake_sys = SimpleNamespace(stdin=stdin, stdout=stdout)

    engines = []

    def make_engine(on_state_change=None):
        engine = _FakeEngine(on_state_change=on_state_change)
        engines.append(engine)
        return engine

    time_values = list(times if times is not None else [0.0] * len(script))

    def fake_monotonic():
        return time_values.pop(0) if time_values else 999.0

    def fake_select(rlist, wlist, xlist, timeout):
        entry = readiness.pop(0) if readiness else "q"
        return ([stdin], [], []) if entry is not None else ([], [], [])

    termios_stub = mock.MagicMock()
    termios_stub.TCSADRAIN = mock.sentinel.TCSADRAIN
    termios_stub.tcgetattr.return_value = mock.sentinel.saved_termios
    tty_stub = mock.MagicMock()

    with mock.patch.object(tui, "sys", fake_sys), \
            mock.patch.object(tui, "termios", termios_stub), \
            mock.patch.object(tui, "tty", tty_stub), \
            mock.patch.object(tui, "select", SimpleNamespace(select=fake_select)), \
            mock.patch.object(tui, "time", SimpleNamespace(monotonic=fake_monotonic)), \
            mock.patch.object(tui, "NoteEngine", make_engine):
        result = tui.main()

    return result, engines[0], stdout.getvalue(), termios_stub, tty_stub


def _strip_ansi(text):
    return re.sub(r"\x1b\[[0-9;]*[a-zA-Z]", "", text)


def test_main_draws_all_ten_keys_in_keyboard_order_with_octave_gap():
    # meridian: unit_id=28faeb62248a requirement=2-1
    _, _, drawn, _, _ = _run_main(["q"])

    plain = _strip_ansi(drawn)
    expected_labels = ["A", "S", "D", "F", "G", "J", "K", "L", ";", "'"]
    assert len(key_order()) == 10

    # All ten keys are present, in physical keyboard order.
    positions = []
    search_from = 0
    for label in expected_labels:
        index = plain.find(" %s " % label, search_from)
        assert index != -1, "key %r missing from display: %r" % (label, plain)
        positions.append(index)
        search_from = index + 1
    assert positions == sorted(positions)

    # A visible gap separates the two octave groups (after G, before J).
    assert " A  S  D  F  G    J  K  L  ;  ' " in plain


def test_main_draws_each_key_in_its_assigned_color():
    # meridian: unit_id=28faeb62248a requirement=2-1
    _, _, drawn, _, _ = _run_main(["q"])

    for name in key_order():
        assert tui._ansi_color(color_for_key(name)) in drawn


