    # meridian: unit_id=28faeb62248a requirement=2-1
    _, engine, _, termios_stub, tty_stub = _run_main(["q"])

    tty_stub.setcbreak.assert_called_once_with(0)
    termios_stub.tcgetattr.assert_called_once_with(0)
    termios_stub.tcsetattr.assert_called_once_with(
        0, termios_stub.TCSADRAIN, mock.sentinel.saved_termios
    )
